    (v_aula_id, 1, $p$À beira-mar, Jesus restaurou Pedro após a tríplice negação com a pergunta "tu me amas?"; como você responderia hoje a essa mesma pergunta feita por Cristo a você?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$Depois de uma queda ou fracasso, você crê que Jesus ainda deseja restaurá-lo e usá-lo, assim como fez com Pedro?$p$, 'reflexao', null),
